<div class="page-heading expense-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Expenses <span>&rsaquo;</span> <b>Categories</b></div><h1>Expense Categories</h1><p>Manage reusable categories for expense records.</p></div><button class="btn btn-danger" type="button" data-category-modal-open>+ Add Category</button></div>
<div class="row g-3 expense-summary"><div class="col-sm-4"><div class="stat-card expense-card-blue"><small>Total Categories</small><strong><?= count($categoryRows) ?></strong><span>All categories</span></div></div><div class="col-sm-4"><div class="stat-card expense-card-green"><small>Active Categories</small><strong><?= count(array_filter($categoryRows,static fn($r)=>$r['status']==='active')) ?></strong><span>Available for expenses</span></div></div><div class="col-sm-4"><div class="stat-card expense-card-red"><small>Inactive Categories</small><strong><?= count(array_filter($categoryRows,static fn($r)=>$r['status']==='inactive')) ?></strong><span>Not available for new records</span></div></div></div>
<div class="admin-panel expense-list"><div class="panel-heading"><h2>Category List</h2><span class="text-muted"><?= count($categoryRows) ?> records</span></div><div class="table-responsive"><table class="table admin-table expense-table"><thead><tr><th>#</th><th>Code</th><th>Category Name</th><th>Description</th><th>Total Expenses</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($categoryRows as $n=>$row): ?><tr><td><?= $n+1 ?></td><td><?= e($row['category_code']) ?></td><td><strong><?= e($row['category_name']) ?></strong></td><td><?= e($row['description']?:'-') ?></td><td><?= (int)$row['expense_count'] ?></td><td><span class="expense-status expense-status-<?= $row['status']==='active'?'paid':'cancelled' ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=expenses-category-edit&amp;id=<?= (int)$row['id'] ?>" title="Edit">&#9998;</a><form method="post" action="index.php?page=admin&amp;section=expenses-category-toggle"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="category_id" value="<?= (int)$row['id'] ?>"><button title="Activate or deactivate">&#9881;</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="category-modal-backdrop" id="category-modal" hidden><div class="category-modal"><div class="category-modal-header"><div><span class="modal-eyebrow">Expenses</span><h2>Add Category</h2></div><button type="button" data-category-modal-close>&times;</button></div><form method="post" action="index.php?page=admin&amp;section=expenses-category-add"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="return_to" value="index.php?page=admin&amp;section=expenses-categories"><label class="form-label">Category Name *<input class="form-control" name="category_name" required autofocus></label><label class="form-label">Description (Optional)<textarea class="form-control" name="description" rows="3"></textarea></label><label class="form-label">Status<select class="form-select" name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><div class="category-modal-actions"><button type="button" class="btn btn-light" data-category-modal-close>Cancel</button><button class="btn btn-danger">Save Category</button></div></form></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){const modal=document.getElementById('category-modal');document.querySelector('[data-category-modal-open]')?.addEventListener('click',()=>modal.hidden=false);document.querySelectorAll('[data-category-modal-close]').forEach(e=>e.addEventListener('click',()=>modal.hidden=true));modal?.addEventListener('click',e=>{if(e.target===modal)modal.hidden=true;});});</script>
